import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    a = []
    for _ in range(n):
        a.append(int(next(iterator)))

    total_xor = 0
    for x in a:
        total_xor ^= x

    if n % 2 == 0:
        if total_xor != 0:
            print("NO")
            return
        else:
            print("YES")
            print(0)
            return
    else:
        if total_xor == 0:
            if len(set(a)) == 1:
                print("YES")
                print(0)
            else:
                print("NO")
            return

        print("YES")
        ops = []

        for i in range(0, n - 2, 2):
            ops.append((i + 1, i + 2, i + 3))

        last_idx = n - 1
        if n >= 3:
            for i in range(0, n - 2, 2): 
                pass

        current_ops_count = len(ops)

        if current_ops_count > n:
            print("NO")
            return

        for op in ops:
            i, j, k = op
            val = a[i-1] ^ a[j-1] ^ a[k-1]
            a[i-1] = val
            a[j-1] = val
            a[k-1] = val

        if len(set(a)) == 1:
            print(len(ops))
            for op in ops:
                print(f"{op[0]} {op[1]} {op[2]}")
        else:
